with filtered as (select *, upper(dept_name) as dept_name_upper, coalesce(dept_name, 'N/A') as dept_name_filled from departments where location in ('Tokyo', 'Singapore', 'New York')) select * from (select dept_name, location, budget from filtered) src pivot (avg(budget) as amount, count(1) as item_count for location in ('London' as london, 'Singapore' as singapore, 'Berlin' as berlin))
